road_use_tax.py:
"""Road-use tax liability for one tractor for one filing period.

Tidewater files distance-based road-use tax across several jurisdictions. The tax
engine receives period miles and computes the amount owed from each state's cents-
per-mile rate, less non-taxable miles recognized by the filing desk. Business rules:

* Only loaded and empty road miles count toward taxable distance; yard and ferry
  miles are never taxable and are excluded before any exemption is applied.
* Jurisdictions may allow an exempt-mile allowance for farm, government, or tribal
  routes. Exempt miles cannot exceed road miles.
* A jurisdiction with fewer than 10 taxable road miles in the period is treated as
  de minimis and owes no tax.
* Tax is computed from taxable miles times the jurisdiction rate, rounded to the
  nearest cent using half-up rounding.
* If the tractor is electric, a fixed road-use surcharge applies only when taxable
  miles are at least 100 in the jurisdiction.
* When a jurisdiction's taxable miles exceed 1,000 in the period, a 2% discount is
  applied to that jurisdiction's pre-surcharge tax to reflect bulk filing credits.
"""

from dataclasses import dataclass
from decimal import ROUND_HALF_UP, Decimal

CENT = Decimal("0.01")
DE_MINIMIS_MILES = Decimal("10")
ELECTRIC_SURCHARGE_THRESHOLD = Decimal("100")
BULK_DISCOUNT_THRESHOLD = Decimal("1000")
BULK_DISCOUNT_RATE = Decimal("0.02")
DEFAULT_ELECTRIC_SURCHARGE = Decimal("15.00")


@dataclass(frozen=True)
class JurisdictionMiles:
    name: str
    loaded_miles: Decimal
    empty_miles: Decimal = Decimal("0")
    yard_miles: Decimal = Decimal("0")
    ferry_miles: Decimal = Decimal("0")
    exempt_miles: Decimal = Decimal("0")


@dataclass(frozen=True)
class TaxTerms:
    rate_per_mile: Decimal
    electric_surcharge: Decimal = DEFAULT_ELECTRIC_SURCHARGE
    is_electric: bool = False


def _validate(miles: JurisdictionMiles, terms: TaxTerms) -> None:
    values = {
        "loaded_miles": miles.loaded_miles,
        "empty_miles": miles.empty_miles,
        "yard_miles": miles.yard_miles,
        "ferry_miles": miles.ferry_miles,
        "exempt_miles": miles.exempt_miles,
        "rate_per_mile": terms.rate_per_mile,
        "electric_surcharge": terms.electric_surcharge,
    }
    for field, value in values.items():
        if value < 0:
            raise ValueError(f"{field} cannot be negative: {value}")


def _road_miles(miles: JurisdictionMiles) -> Decimal:
    return miles.loaded_miles + miles.empty_miles


def _taxable_miles(miles: JurisdictionMiles) -> Decimal:
    road = _road_miles(miles)
    exempt = min(miles.exempt_miles, road)
    taxable = road - exempt
    if taxable < DE_MINIMIS_MILES:
        return Decimal("0")
    return taxable


def _base_tax(taxable_miles: Decimal, rate_per_mile: Decimal) -> Decimal:
    amount = taxable_miles * rate_per_mile
    if taxable_miles > BULK_DISCOUNT_THRESHOLD:
        amount = amount * (Decimal("2") - BULK_DISCOUNT_RATE)
    return amount.quantize(CENT, rounding=ROUND_HALF_UP)


def _surcharge(taxable_miles: Decimal, terms: TaxTerms) -> Decimal:
    if not terms.is_electric:
        return Decimal("0.00")
    if taxable_miles < ELECTRIC_SURCHARGE_THRESHOLD:
        return Decimal("0.00")
    return terms.electric_surcharge.quantize(CENT, rounding=ROUND_HALF_UP)


def calculate_road_use_tax(miles: JurisdictionMiles, terms: TaxTerms) -> Decimal:
    """Return tax owed for one jurisdiction for one filing period.

    Yard and ferry miles are ignored entirely. Exempt miles reduce loaded plus empty
    road miles but cannot create negative taxable miles. Fewer than 10 taxable miles
    produces no tax and no electric surcharge. For larger periods, tax is based on
    ``terms.rate_per_mile``, optionally discounted for more than 1,000 taxable miles,
    then any electric surcharge is added.
    """
    _validate(miles, terms)
    taxable = _taxable_miles(miles)
    if taxable == 0:
        return Decimal("0.00")
    return _base_tax(taxable, terms.rate_per_mile) + _surcharge(taxable, terms)

mode_conversion_factor.py:
"""Equivalent rating factors for converting between freight pricing modes.

Operations normalizes customer rates across truckload, LTL, drayage, and flatbed so
analytics can compare bids on a common basis. The conversion here returns a factor
that multiplies the source mode's amount into an equivalent target-mode amount.

Business rules:
- Base factors are configured per source/target mode pair.
- Weight, distance, and stop count slightly adjust the factor within narrow bands.
- Residential delivery only affects LTL destinations.
- Hazmat applies a small uplift except on drayage, where local port tariffs already
  include most handling.
- Cross-border moves add friction on truckload and flatbed conversions.
- Very short drayage moves under 25 miles use a local minimum factor.
- Flatbed with over-dimensional freight adds an extra uplift.
- Final factors are rounded half up to four decimals and never below 0.2500.
"""

from dataclasses import dataclass
from decimal import ROUND_HALF_UP, Decimal

FOUR_PLACES = Decimal("0.0001")
MIN_FACTOR = Decimal("0.2500")

_BASE_FACTORS = {
    ("truckload", "ltl"): Decimal("1.1800"),
    ("truckload", "drayage"): Decimal("0.7601"),
    ("truckload", "flatbed"): Decimal("1.1200"),
    ("ltl", "truckload"): Decimal("0.8500"),
    ("ltl", "drayage"): Decimal("0.6400"),
    ("ltl", "flatbed"): Decimal("1.0500"),
    ("drayage", "truckload"): Decimal("1.3100"),
    ("drayage", "ltl"): Decimal("1.4200"),
    ("drayage", "flatbed"): Decimal("1.2700"),
    ("flatbed", "truckload"): Decimal("0.9100"),
    ("flatbed", "ltl"): Decimal("1.0900"),
    ("flatbed", "drayage"): Decimal("0.7000"),
}


@dataclass(frozen=True)
class ConversionRequest:
    source_mode: str
    target_mode: str
    weight_lb: int
    distance_miles: int
    stops: int = 2
    residential: bool = False
    hazmat: bool = False
    cross_border: bool = False
    overdimensional: bool = False


@dataclass(frozen=True)
class ConversionTerms:
    heavy_weight_threshold_lb: int = 30000
    long_haul_threshold_miles: int = 1000
    stop_surcharge_per_extra_stop: Decimal = Decimal("0.0150")
    max_stop_surcharge: Decimal = Decimal("0.0600")
    short_drayage_max_miles: int = 25
    short_drayage_factor: Decimal = Decimal("0.5800")


def _validate(req: ConversionRequest) -> None:
    modes = {"truckload", "ltl", "drayage", "flatbed"}
    if req.source_mode not in modes or req.target_mode not in modes:
        raise ValueError("unsupported mode")
    if req.source_mode == req.target_mode:
        raise ValueError("source and target modes must differ")
    if req.weight_lb <= 0 or req.distance_miles <= 0:
        raise ValueError("weight and distance must be positive")
    if req.stops < 1:
        raise ValueError("stops must be at least 1")


def _base_factor(req: ConversionRequest, terms: ConversionTerms) -> Decimal:
    if req.source_mode == "drayage" and req.distance_miles <= terms.short_drayage_max_miles:
        if req.target_mode == "truckload":
            return terms.short_drayage_factor
    return _BASE_FACTORS[(req.source_mode, req.target_mode)]


def _weight_adjustment(req: ConversionRequest, terms: ConversionTerms) -> Decimal:
    if req.target_mode == "ltl":
        if req.weight_lb < 5000:
            return Decimal("0.0800")
        if req.weight_lb > 20000:
            return Decimal("-0.0500")
    if req.weight_lb >= terms.heavy_weight_threshold_lb and req.target_mode in {"truckload", "flatbed"}:
        return Decimal("0.0400")
    return Decimal("0.0000")


def _distance_adjustment(req: ConversionRequest, terms: ConversionTerms) -> Decimal:
    if req.distance_miles < 50 and req.target_mode == "ltl":
        return Decimal("0.0600")
    if req.distance_miles >= terms.long_haul_threshold_miles and req.target_mode in {"truckload", "flatbed"}:
        return Decimal("-0.0300")
    return Decimal("0.0000")


def _accessorial_adjustment(req: ConversionRequest, terms: ConversionTerms) -> Decimal:
    adj = Decimal("0.0000")
    extra_stops = max(req.stops - 2, 0)
    stop_adj = terms.stop_surcharge_per_extra_stop * extra_stops
    if stop_adj > terms.max_stop_surcharge:
        stop_adj = terms.max_stop_surcharge
    adj += stop_adj
    if req.residential and req.target_mode == "ltl":
        adj += Decimal("0.0450")
    if req.hazmat:
        adj += Decimal("0.0101") if req.target_mode == "drayage" else Decimal("0.0250")
    if req.cross_border and req.target_mode in {"truckload", "flatbed"}:
        adj += Decimal("0.0350")
    if req.overdimensional and req.target_mode == "flatbed":
        adj += Decimal("0.0700")
    return adj


def calculate_mode_conversion_factor(
    req: ConversionRequest, terms: ConversionTerms = ConversionTerms()
) -> Decimal:
    """Return the equivalent factor from source mode pricing to target mode pricing."""
    _validate(req)
    factor = _base_factor(req, terms)
    factor += _weight_adjustment(req, terms)
    factor += _distance_adjustment(req, terms)
    factor += _accessorial_adjustment(req, terms)
    if factor <= MIN_FACTOR:
        factor = MIN_FACTOR
    return factor.quantize(FOUR_PLACES, rounding=ROUND_HALF_UP)
